declare(strict_types=1);require_once __DIR__.'/includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('browse.php');verify_csrf();$rid=(int)($_POST['recipe_id']??0);$rating=(int)($_POST['rating']??0);if($rating<1||$rating>5){flash('error','Choose a rating from 1 to 5.');redirect('recipe.php?id='.$rid);} $stmt=db()->prepare('INSERT INTO ratings(user_id,recipe_id,rating) VALUES(?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),updated_at=NOW()');$stmt->execute([current_user()['id'],$rid,$rating]);audit('RATE_RECIPE',$rid,'Rating '.$rating);flash('success','Your rating was saved.');redirect('recipe.php?id='.$rid);
